#!/usr/bin/env python3
import math
import sys


BASES = "ACGT"
INDEX = {base: i for i, base in enumerate(BASES)}
COMP_INDEX = [3, 2, 1, 0]


def read_fasta(path):
    name = None
    chunks = []
    with open(path) as handle:
        for raw in handle:
            line = raw.strip()
            if not line:
                continue
            if line.startswith(">"):
                if name is not None:
                    yield name, "".join(chunks).upper()
                name = line[1:]
                chunks = []
            else:
                chunks.append(line)
    if name is not None:
        yield name, "".join(chunks).upper()


def read_weights(path):
    with open(path) as handle:
        for line_no, raw in enumerate(handle, 1):
            if not raw.strip() or raw.startswith("#"):
                continue
            fields = raw.rstrip("\n").split("\t")
            if len(fields) < 3:
                raise ValueError("BED line %d has fewer than three columns" % line_no)
            weight = int(fields[4]) if len(fields) >= 5 else 1
            yield fields[0], int(fields[1]), int(fields[2]), weight
